'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var erfinv = require( '@stdlib/math/base/special/erfinv' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var PINF = require( '@stdlib/constants/float64/pinf' );


// MAIN //

/**
* Returns a function for evaluating the quantile function for a Half-normal distribution with scale parameter `sigma`.
*
* @param {NonNegativeNumber} sigma - scale parameter
* @returns {Function} quantile function
*
* @example
* var myquantile = factory( 1.0 );
* var y = myquantile( 0.2 );
* // returns ~0.253
*
* y = myquantile( 0.8 );
* // returns ~1.282
*/
function factory( sigma ) {
	if ( isnan( sigma ) || sigma < 0.0 ) {
		return constantFunction( NaN );
	}
	if ( sigma === 0.0 ) {
		return constantFunction( 0.0 );
	}
	return quantile;

	/**
	* Evaluates the quantile function for a Half-normal distribution.
	*
	* @private
	* @param {Probability} p - input value
	* @returns {number} evaluated quantile function
	*
	* @example
	* var y = quantile( 0.3 );
	* // returns <number>
	*/
	function quantile( p ) {
		if ( isnan( p ) || p < 0.0 || p > 1.0 ) {
			return NaN;
		}
		if ( p === 1.0 ) {
			return PINF;
		}
		return sigma * SQRT2 * erfinv( p );
	}
}


// EXPORTS //

module.exports = factory;
